import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"Page 22 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"22","title":"Page 22 | Home","prev":"/page/21/","next":"/page/23/","posts":[{"title":"如何封装第三方vue组件","url":"/posts/2018-05-29-wrapper-vue-component/","date":"2018-05-29 23:19","tags":["js","vue"],"html":"<p>终于算是正式接触 SPA 的前端工作了，最近在解决很多 Vue 组件的问题，其中就有一个针对第三方组件的定制化需求，花了不少时间来折腾。</p>\\n<h2 id=\\"解决-v-model-绑定\\" tabindex=\\"-1\\">解决 v-model 绑定 <a class=\\"header-anchor\\" href=\\"#解决-v-model-绑定\\" aria-label=\\"Permalink to &quot;解决 v-model 绑定&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这次封装的就是 element 的前端 vue 框架，因为框架本身对 iOS 兼容性不好，所以需要二次封装。封装的是一个 select 组件。所以需要数据的双向绑定，官方教程也已经解释了。\\n<a href=\\"https://vuejs.org/v2/guide/components-custom-events.html#Customizing-Component-v-model\\" target=\\"_blank\\" rel=\\"noreferrer\\">v-model</a> 本质上就是绑定一个值和监听相应的事件。\\n这次本质是封装的一个 input 元素，所以我们需要手动绑定 value 和监听事件。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-bind:value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> v-on</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$listeners\\"</span><span style=\\"color:#24292E\\">>&#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>官方文档也解释了这个内置变量的用法<a href=\\"https://vuejs.org/v2/api/#vm-listeners\\" target=\\"_blank\\" rel=\\"noreferrer\\">vm-listeners</a></p>\\n<h2 id=\\"继承父元素的属性\\" tabindex=\\"-1\\">继承父元素的属性 <a class=\\"header-anchor\\" href=\\"#继承父元素的属性\\" aria-label=\\"Permalink to &quot;继承父元素的属性&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>父元素的属性继承可以使用<code>v-bind=&quot;$attrs&quot;</code>来完成。所以完成组建的透明封装只需要加上三个指令。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#6F42C1\\"> v-bind</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$attrs\\"</span><span style=\\"color:#6F42C1\\"> v-bind:value</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"value\\"</span><span style=\\"color:#6F42C1\\"> v-on</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"$listeners\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#22863A\\">el-select</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">template</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>虽然知道答案之后很简单，但是探索的过程中还是比较花时间的。希望能帮助大家解决这个问题，如果有什么疏漏之处，也请大家指正。</p>\\n"},{"title":"JavaScript开发中的性能优化","url":"/posts/2018-04-25-javascript-performance/","date":"2018-04-25 23:22","tags":["js","performance"],"html":"<p>最近工作比较清闲，5 月又换了一个工作环境。总结下最近看的有关 JavaScript 性能的知识，并记下来供未来的自己参考。希望自己能不忘初心，继续成长！</p>\\n<h2 id=\\"使用-requestanimationframe-来更新动画\\" tabindex=\\"-1\\">使用 requestAnimationFrame 来更新动画 <a class=\\"header-anchor\\" href=\\"#使用-requestanimationframe-来更新动画\\" aria-label=\\"Permalink to &quot;使用 requestAnimationFrame 来更新动画&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>使用<code>requestAnimationFrame</code>把动画渲染交给浏览器，可以保证渲染保持在 60FPS。应该避免使用<code>setTimeout</code>或者<code>setInterval</code>来实现动画，因为计时器和事件队列会消耗更多的资源，还会导致无用的页面重新绘制。</p>\\n<h2 id=\\"使用-web-workers-来进行复杂的运算\\" tabindex=\\"-1\\">使用 Web Workers 来进行复杂的运算 <a class=\\"header-anchor\\" href=\\"#使用-web-workers-来进行复杂的运算\\" aria-label=\\"Permalink to &quot;使用 Web Workers 来进行复杂的运算&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以把单纯的计算放在 Web Workers 中，这样不影响主页面的渲染和流畅，例如加密和矩阵变换的运算就可以完全放在 Web Workers 中来减少主线程的执行时间，避免浏览器渲染堵塞。</p>\\n<h2 id=\\"避免微优化-javascript\\" tabindex=\\"-1\\">避免微优化 JavaScript <a class=\\"header-anchor\\" href=\\"#避免微优化-javascript\\" aria-label=\\"Permalink to &quot;避免微优化 JavaScript&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>举个最简单的例子，我曾经在一本书上看到过一个提升程序效率的例子。大致是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>这里的<code>array.length</code>获取数组的长度，每次都要计算数组长度会消耗不少时间，优化之后的代码是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> len </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>通过缓存数组的长度来保证只计算一次。这就是典型的微优化，说实话这段代码我一直在用，直到最近读了其他的书才发现，现在的 JS 解释器早就优化了对数组长度的计算。无论是读取一次还是一万次消耗的时间都没有太大差别。微优化应该是 JS 引擎需要做的事情，我们不应该在实际开发中在这方面耗费过多的时间。</p>\\n<h2 id=\\"滑动事件优化\\" tabindex=\\"-1\\">滑动事件优化 <a class=\\"header-anchor\\" href=\\"#滑动事件优化\\" aria-label=\\"Permalink to &quot;滑动事件优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当用户监听滑动事件并执行相关动画操作的时候，记得使用<code>window.requestAnimationFrame</code>来优化动画的执行。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> onScroll</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">evt</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // Prevent multiple rAF callbacks.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (scheduledAnimationFrame) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  scheduledAnimationFrame </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> readAndUpdatePage</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // do something</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">addEventListener</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'scroll'</span><span style=\\"color:#24292E\\">, onScroll);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br></div></div><p>参考：</p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/debounce-your-input-handlers\\" target=\\"_blank\\" rel=\\"noreferrer\\">Debounce Your Input Handlers</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/optimize-javascript-execution\\" target=\\"_blank\\" rel=\\"noreferrer\\">Optimize JavaScript Execution</a></p>\\n"},{"title":"使用letsencrypt为自己的网站加密","url":"/posts/2018-04-08-website-https/","date":"2018-04-08 20:51","tags":["site","ssl"],"html":"<p>好吧，这次博客的更新稍微有点迟到了。因为自己各种忙着考驾照什么的，不过新的一年又要有新的开始了。最近买了 VPS 也就开始折腾起来了，讲讲如何用 letsencrypt 来给自己的网站颁发不要钱的证书，而且最近还支持通配符的二级域名了，想怎么开子网站都行！！！</p>\\n<h2 id=\\"dehydrated\\" tabindex=\\"-1\\">dehydrated <a class=\\"header-anchor\\" href=\\"#dehydrated\\" aria-label=\\"Permalink to &quot;dehydrated&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>浏览器的证书签名的步骤实在是很麻烦，所以有位热心的学生做了一个自动化脚本，可以自动生成脚本并且可以和其他脚本一起使用。达到一键签名证书。</p>\\n<h2 id=\\"letsencrypt-cloudflare-hook\\" tabindex=\\"-1\\">letsencrypt-cloudflare-hook <a class=\\"header-anchor\\" href=\\"#letsencrypt-cloudflare-hook\\" aria-label=\\"Permalink to &quot;letsencrypt-cloudflare-hook&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我把自己的 DNS 服务托管到 cloudflare 上，还可以使用 cloudflare 提供免费的 CDN 服务。最重要的一点是 cloudflare 有 API 接口。利用这个接口就可以自动完成 DNS-01 challenge。简单的来说，就是通过添加一条 DNS 记录来证明自己对这个域名的所有权，才能给这个域名颁发证书。</p>\\n<h2 id=\\"安装过程\\" tabindex=\\"-1\\">安装过程 <a class=\\"header-anchor\\" href=\\"#安装过程\\" aria-label=\\"Permalink to &quot;安装过程&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>知道了这两个工具之后，我们就可以开始配置证书了。具体的流程都写在项目的<a href=\\"https://github.com/kappataumu/letsencrypt-cloudflare-hook/blob/master/README.md\\" target=\\"_blank\\" rel=\\"noreferrer\\">文档</a>里面了。我这里主要是讲述下遇到的坑，首先我自己的服务器环境是 CentOS7，使用的是默认的 python2 的环境。需要安装<code>cryptography</code>的库才能顺利完成编译。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> yum</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> gcc</span><span style=\\"color:#032F62\\"> libffi-devel</span><span style=\\"color:#032F62\\"> python-devel</span><span style=\\"color:#032F62\\"> openssl-devel</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>其次，配置环境最好保存在<code>dehydrated/config</code>里，这样就没必要每次都设置环境变量。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_EMAIL=user@example.com\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_KEY=K9uX2HyUjeWg5AhAb\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_DEBUG=true\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>CF_KEY 就是 cloudflare 里面的 Global API Key，替换一下就好了。因为我们要配置的域名包含所有的二级域名，所以需要新建一个<code>dehydrated/domains.txt</code>文件，并写入：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>icehoney.me *.icehoney.me</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样就会对主域名和所有二级域名生效。</p>\\n<p>之后再执行命令，<code>./dehydrated -c -t dns-01 -k 'hooks/cloudflare/hook.py'</code>。如果没有问题就可以看到成功生成的日志。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://github.com/lukas2511/dehydrated\\" target=\\"_blank\\" rel=\\"noreferrer\\">dehydrated</a></p>\\n<p><a href=\\"https://github.com/kappataumu/letsencrypt-cloudflare-hook\\" target=\\"_blank\\" rel=\\"noreferrer\\">letsencrypt-cloudflare-hook</a></p>\\n<p><a href=\\"https://stackoverflow.com/questions/22073516/failed-to-install-python-cryptography-package-with-pip-and-setup-py\\" target=\\"_blank\\" rel=\\"noreferrer\\">Failed to install Python Cryptography package with PIP and setup.py\\nAsk Question</a></p>\\n"}]},"relativePath":"page/22/index.md","filePath":"page/[page].md"}`),e={name:"page/22/index.md"};function l(p,o,r,t,c,i){return a(),n("div")}const u=s(e,[["render",l]]);export{y as __pageData,u as default};
